INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter BYOD?', 2, '[{"text": "Nutzung persönlicher Geräte für Arbeit", "correct": true, "because": "Bring Your Own Device"}, {"text": "Firmeneigene Geräte bereitstellen", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt eine BYOD-Richtlinie?', 3, '[{"text": "Flexibilität und Kostenersparnis", "correct": true, "because": "Mitarbeitergeräte nutzen"}, {"text": "Hardwarekosten erhöhen", "correct": false, "because": "Kein Ziel"}, {"text": "Design verbessern", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu einer BYOD-Richtlinie?', 5, '[{"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Daten schützen"}, {"text": "Nutzungsregeln", "correct": true, "because": "Akzeptable Nutzung"}, {"text": "Büroverschönerung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) BYOD erlaubt private Geräte für Arbeit. b) Es erhöht automatisch die Sicherheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheitsrisiken möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei BYOD?', 4, '[{"text": "Sicherheitsrichtlinien", "correct": false, "because": "Kernaufgabe"}, {"text": "Gerätekompatibilität", "correct": false, "because": "Wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob BYOD Sicherheitsmaßnahmen erfordert?', 2, '[{"text": "Ja", "correct": true, "because": "Datenschutz"}, {"text": "Nein", "correct": false, "because": "Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft für BYOD-Sicherheit verwendet?', 3, '[{"text": "MDM", "correct": true, "because": "Mobile Device Management"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Umsetzung von BYOD?', 5, '[{"text": "Sicherheitsrichtlinie", "correct": true, "because": "Schutzmaßnahmen"}, {"text": "Mitarbeiterschulung", "correct": true, "because": "Bewusstsein"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) BYOD spart Kosten für Geräte. b) Es ist immer sicherer als Firmengeräte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheitsrisiken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei BYOD unwichtig?', 4, '[{"text": "Datensicherheit", "correct": false, "because": "Hauptaspekt"}, {"text": "Nutzungsvereinbarung", "correct": false, "because": "Regeln"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss BYOD eine Sicherheitsrichtlinie haben?', 2, '[{"text": "Ja", "correct": true, "because": "Datenschutz"}, {"text": "Nein", "correct": false, "because": "Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet BYOD für Unternehmen?', 4, '[{"text": "Kostenersparnis", "correct": true, "because": "Weniger Geräte"}, {"text": "Mitarbeiterflexibilität", "correct": true, "because": "Eigene Geräte"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass BYOD immer sicher ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheitsmaßnahmen nötig"}, {"text": "Ja", "correct": false, "because": "Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei BYOD?', 3, '[{"text": "Datensicherheit", "correct": true, "because": "Schutz wichtig"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) BYOD nutzt persönliche Geräte. b) Es erfordert keine Sicherheitsmaßnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat BYOD?', 5, '[{"text": "Sicherheitsrisiken", "correct": true, "because": "Private Geräte"}, {"text": "Komplexere Verwaltung", "correct": true, "because": "Diverse Geräte"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei BYOD?', 3, '[{"text": "Sicherheitsrichtlinien umsetzen", "correct": true, "because": "Datenschutz"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann BYOD Sicherheitssoftware erfordern?', 2, '[{"text": "Ja", "correct": true, "because": "Schutzmaßnahmen"}, {"text": "Nein", "correct": false, "because": "Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für BYOD nutzen?', 4, '[{"text": "Microsoft Intune", "correct": true, "because": "MDM-Lösung"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
